    n = output.shape[-1]
    batch = output.shape[0]
    block = _G2048_N
    key = id(output)
    stage_entry = _g2048_stage_cache.get(key)
    if stage_entry is None or stage_entry[0] is not output:
        first_panel_ctas = (
            148
            if (batch, n) in ((4, 1024), (2, 2048))
            else _G2048_FIRST_PANEL_CTAS
        )
        stages = []
        for panel_index, panel_origin in enumerate(range(0, n, block)):
            stop = panel_origin + block
            launch_args = (
                np.int64(n),
                np.int64(n * n),
                np.int64(panel_origin),
            )
            if stop == n:
                stages.append((launch_args, panel_index, None))
                continue
            panel = output[:, panel_origin:stop, stop:]
            trailing_input = data[:, stop:, stop:]
            trailing_output = output[:, stop:, stop:]
            panel_pointer = cute_runtime.make_ptr(
                cutlass.Float32,
                panel.data_ptr(),
                cute.AddressSpace.gmem,
                assumed_align=16,
            )
